DROP TRIGGER IF EXISTS attempt_spend_attempt_insert;

CREATE TRIGGER IF NOT EXISTS attempt_spend_attempt_insert AFTER INSERT ON agent_run_attempts BEGIN DELETE FROM attempt_spend WHERE (project_id,run_id,attempt_id) IN (SELECT project_id,run_id,attempt_id FROM (SELECT NEW.project_id AS project_id,NEW.run_id AS run_id,NEW.attempt_id AS attempt_id))
      AND NOT EXISTS (SELECT 1 FROM agent_run_attempts a JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id
        WHERE a.project_id=attempt_spend.project_id AND a.run_id=attempt_spend.run_id AND a.attempt_id=attempt_spend.attempt_id AND r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')); INSERT INTO attempt_spend(project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,counted)
      SELECT project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,CASE WHEN live=1 THEN 1 WHEN claimed_at<=NULL THEN 0 ELSE 1 END FROM (SELECT a.project_id,a.run_id,a.attempt_id,a.claimed_at,COALESCE(r.origin,CASE WHEN CASE WHEN json_valid(r.dispatch_spec) THEN CASE WHEN json_type(r.dispatch_spec, '$.actor') = 'text' THEN NULLIF(json_extract(r.dispatch_spec, '$.actor'), '') END END IN ('clock','backfill','deployment') THEN 'automatic' ELSE 'manual' END) AS origin,r.task,
    COALESCE(a.cost_usd,a.estimate_usd,CASE WHEN r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by THEN r.cost_usd END,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS value,
    COALESCE(a.estimate_usd,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS estimate,
    CASE WHEN a.cost_usd IS NOT NULL THEN COALESCE(a.cost_source,'actual')
      WHEN a.estimate_usd IS NULL AND r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by AND r.cost_usd IS NOT NULL THEN COALESCE(r.cost_source,'actual')
      ELSE a.cost_source END AS cost_source,
    CASE WHEN r.status IN ('pending', 'running') AND r.dispatched_by IS a.attempt_id THEN 1 ELSE 0 END AS live
    FROM (SELECT NEW.project_id AS project_id,NEW.run_id AS run_id,NEW.attempt_id AS attempt_id) k JOIN agent_run_attempts a ON a.project_id=k.project_id AND a.run_id=k.run_id AND a.attempt_id=k.attempt_id
    JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id WHERE r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')) WHERE true
      ON CONFLICT(project_id,run_id,attempt_id) DO UPDATE SET claimed_at=excluded.claimed_at,origin=excluded.origin,task=excluded.task,value=excluded.value,estimate=excluded.estimate,cost_source=excluded.cost_source,live=excluded.live,counted=CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END
      WHERE (attempt_spend.claimed_at,attempt_spend.origin,attempt_spend.task,attempt_spend.value,attempt_spend.estimate,attempt_spend.cost_source,attempt_spend.live,attempt_spend.counted) IS NOT (excluded.claimed_at,excluded.origin,excluded.task,excluded.value,excluded.estimate,excluded.cost_source,excluded.live,CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END); UPDATE attempt_spend SET counted=0 WHERE (project_id,run_id,attempt_id) IN (SELECT project_id,run_id,attempt_id FROM attempt_spend
  WHERE counted=1 AND live=0 AND claimed_at<=NEW.claimed_at-86400000 ORDER BY claimed_at LIMIT 8); END;

DROP TRIGGER IF EXISTS attempt_spend_attempt_update;

CREATE TRIGGER IF NOT EXISTS attempt_spend_attempt_update AFTER UPDATE OF claimed_at,estimate_usd,cost_usd,cost_source ON agent_run_attempts WHEN OLD.claimed_at IS NOT NEW.claimed_at OR OLD.estimate_usd IS NOT NEW.estimate_usd OR OLD.cost_usd IS NOT NEW.cost_usd OR OLD.cost_source IS NOT NEW.cost_source BEGIN DELETE FROM attempt_spend WHERE (project_id,run_id,attempt_id) IN (SELECT project_id,run_id,attempt_id FROM (SELECT NEW.project_id AS project_id,NEW.run_id AS run_id,NEW.attempt_id AS attempt_id))
      AND NOT EXISTS (SELECT 1 FROM agent_run_attempts a JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id
        WHERE a.project_id=attempt_spend.project_id AND a.run_id=attempt_spend.run_id AND a.attempt_id=attempt_spend.attempt_id AND r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')); INSERT INTO attempt_spend(project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,counted)
      SELECT project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,CASE WHEN live=1 THEN 1 WHEN claimed_at<=NULL THEN 0 ELSE 1 END FROM (SELECT a.project_id,a.run_id,a.attempt_id,a.claimed_at,COALESCE(r.origin,CASE WHEN CASE WHEN json_valid(r.dispatch_spec) THEN CASE WHEN json_type(r.dispatch_spec, '$.actor') = 'text' THEN NULLIF(json_extract(r.dispatch_spec, '$.actor'), '') END END IN ('clock','backfill','deployment') THEN 'automatic' ELSE 'manual' END) AS origin,r.task,
    COALESCE(a.cost_usd,a.estimate_usd,CASE WHEN r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by THEN r.cost_usd END,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS value,
    COALESCE(a.estimate_usd,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS estimate,
    CASE WHEN a.cost_usd IS NOT NULL THEN COALESCE(a.cost_source,'actual')
      WHEN a.estimate_usd IS NULL AND r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by AND r.cost_usd IS NOT NULL THEN COALESCE(r.cost_source,'actual')
      ELSE a.cost_source END AS cost_source,
    CASE WHEN r.status IN ('pending', 'running') AND r.dispatched_by IS a.attempt_id THEN 1 ELSE 0 END AS live
    FROM (SELECT NEW.project_id AS project_id,NEW.run_id AS run_id,NEW.attempt_id AS attempt_id) k JOIN agent_run_attempts a ON a.project_id=k.project_id AND a.run_id=k.run_id AND a.attempt_id=k.attempt_id
    JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id WHERE r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')) WHERE true
      ON CONFLICT(project_id,run_id,attempt_id) DO UPDATE SET claimed_at=excluded.claimed_at,origin=excluded.origin,task=excluded.task,value=excluded.value,estimate=excluded.estimate,cost_source=excluded.cost_source,live=excluded.live,counted=CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END
      WHERE (attempt_spend.claimed_at,attempt_spend.origin,attempt_spend.task,attempt_spend.value,attempt_spend.estimate,attempt_spend.cost_source,attempt_spend.live,attempt_spend.counted) IS NOT (excluded.claimed_at,excluded.origin,excluded.task,excluded.value,excluded.estimate,excluded.cost_source,excluded.live,CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END); END;

DROP TRIGGER IF EXISTS attempt_spend_attempt_delete;

CREATE TRIGGER IF NOT EXISTS attempt_spend_attempt_delete AFTER DELETE ON agent_run_attempts BEGIN DELETE FROM attempt_spend WHERE project_id=OLD.project_id AND run_id=OLD.run_id AND attempt_id=OLD.attempt_id; END;

DROP TRIGGER IF EXISTS attempt_spend_run_update;

CREATE TRIGGER IF NOT EXISTS attempt_spend_run_update AFTER UPDATE OF status,dispatched_by,cost_usd,cost_source ON agent_runs WHEN (OLD.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed') OR NEW.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')) AND (OLD.status IS NOT NEW.status OR OLD.dispatched_by IS NOT NEW.dispatched_by OR OLD.cost_usd IS NOT NEW.cost_usd OR OLD.cost_source IS NOT NEW.cost_source) BEGIN DELETE FROM attempt_spend WHERE (project_id,run_id,attempt_id) IN (SELECT project_id,run_id,attempt_id FROM (SELECT NEW.project_id AS project_id,NEW.id AS run_id,OLD.dispatched_by AS attempt_id WHERE OLD.dispatched_by IS NOT NULL
  UNION SELECT NEW.project_id,NEW.id,NEW.dispatched_by WHERE NEW.dispatched_by IS NOT NULL))
      AND NOT EXISTS (SELECT 1 FROM agent_run_attempts a JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id
        WHERE a.project_id=attempt_spend.project_id AND a.run_id=attempt_spend.run_id AND a.attempt_id=attempt_spend.attempt_id AND r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')); INSERT INTO attempt_spend(project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,counted)
      SELECT project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,CASE WHEN live=1 THEN 1 WHEN claimed_at<=NULL THEN 0 ELSE 1 END FROM (SELECT a.project_id,a.run_id,a.attempt_id,a.claimed_at,COALESCE(r.origin,CASE WHEN CASE WHEN json_valid(r.dispatch_spec) THEN CASE WHEN json_type(r.dispatch_spec, '$.actor') = 'text' THEN NULLIF(json_extract(r.dispatch_spec, '$.actor'), '') END END IN ('clock','backfill','deployment') THEN 'automatic' ELSE 'manual' END) AS origin,r.task,
    COALESCE(a.cost_usd,a.estimate_usd,CASE WHEN r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by THEN r.cost_usd END,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS value,
    COALESCE(a.estimate_usd,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS estimate,
    CASE WHEN a.cost_usd IS NOT NULL THEN COALESCE(a.cost_source,'actual')
      WHEN a.estimate_usd IS NULL AND r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by AND r.cost_usd IS NOT NULL THEN COALESCE(r.cost_source,'actual')
      ELSE a.cost_source END AS cost_source,
    CASE WHEN r.status IN ('pending', 'running') AND r.dispatched_by IS a.attempt_id THEN 1 ELSE 0 END AS live
    FROM (SELECT NEW.project_id AS project_id,NEW.id AS run_id,OLD.dispatched_by AS attempt_id WHERE OLD.dispatched_by IS NOT NULL
  UNION SELECT NEW.project_id,NEW.id,NEW.dispatched_by WHERE NEW.dispatched_by IS NOT NULL) k JOIN agent_run_attempts a ON a.project_id=k.project_id AND a.run_id=k.run_id AND a.attempt_id=k.attempt_id
    JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id WHERE r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')) WHERE true
      ON CONFLICT(project_id,run_id,attempt_id) DO UPDATE SET claimed_at=excluded.claimed_at,origin=excluded.origin,task=excluded.task,value=excluded.value,estimate=excluded.estimate,cost_source=excluded.cost_source,live=excluded.live,counted=CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END
      WHERE (attempt_spend.claimed_at,attempt_spend.origin,attempt_spend.task,attempt_spend.value,attempt_spend.estimate,attempt_spend.cost_source,attempt_spend.live,attempt_spend.counted) IS NOT (excluded.claimed_at,excluded.origin,excluded.task,excluded.value,excluded.estimate,excluded.cost_source,excluded.live,CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END); END;

DROP TRIGGER IF EXISTS attempt_spend_run_reclassify;

CREATE TRIGGER IF NOT EXISTS attempt_spend_run_reclassify AFTER UPDATE OF task,origin ON agent_runs WHEN (OLD.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed') OR NEW.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')) AND (OLD.task IS NOT NEW.task OR OLD.origin IS NOT NEW.origin) BEGIN DELETE FROM attempt_spend WHERE (project_id,run_id,attempt_id) IN (SELECT project_id,run_id,attempt_id FROM (SELECT project_id,run_id,attempt_id FROM agent_run_attempts WHERE project_id=NEW.project_id AND run_id=NEW.id))
      AND NOT EXISTS (SELECT 1 FROM agent_run_attempts a JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id
        WHERE a.project_id=attempt_spend.project_id AND a.run_id=attempt_spend.run_id AND a.attempt_id=attempt_spend.attempt_id AND r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')); INSERT INTO attempt_spend(project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,counted)
      SELECT project_id,run_id,attempt_id,claimed_at,origin,task,value,estimate,cost_source,live,CASE WHEN live=1 THEN 1 WHEN claimed_at<=NULL THEN 0 ELSE 1 END FROM (SELECT a.project_id,a.run_id,a.attempt_id,a.claimed_at,COALESCE(r.origin,CASE WHEN CASE WHEN json_valid(r.dispatch_spec) THEN CASE WHEN json_type(r.dispatch_spec, '$.actor') = 'text' THEN NULLIF(json_extract(r.dispatch_spec, '$.actor'), '') END END IN ('clock','backfill','deployment') THEN 'automatic' ELSE 'manual' END) AS origin,r.task,
    COALESCE(a.cost_usd,a.estimate_usd,CASE WHEN r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by THEN r.cost_usd END,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS value,
    COALESCE(a.estimate_usd,CASE r.task WHEN 'title-summary' THEN 0.1 WHEN 'canopy-map' THEN 1 WHEN 'extract-curate' THEN 0.5 WHEN 'turn-cards' THEN 0.05 WHEN 'curate-spores' THEN 0.25 WHEN 'curate-plans' THEN 0.25 WHEN 'vault-seed' THEN 1 ELSE 1 END) AS estimate,
    CASE WHEN a.cost_usd IS NOT NULL THEN COALESCE(a.cost_source,'actual')
      WHEN a.estimate_usd IS NULL AND r.status IN ('completed','failed','skipped') AND a.attempt_id=r.dispatched_by AND r.cost_usd IS NOT NULL THEN COALESCE(r.cost_source,'actual')
      ELSE a.cost_source END AS cost_source,
    CASE WHEN r.status IN ('pending', 'running') AND r.dispatched_by IS a.attempt_id THEN 1 ELSE 0 END AS live
    FROM (SELECT project_id,run_id,attempt_id FROM agent_run_attempts WHERE project_id=NEW.project_id AND run_id=NEW.id) k JOIN agent_run_attempts a ON a.project_id=k.project_id AND a.run_id=k.run_id AND a.attempt_id=k.attempt_id
    JOIN agent_runs r ON r.project_id=a.project_id AND r.id=a.run_id WHERE r.task IN ('title-summary','extract-curate','turn-cards','curate-spores','curate-plans','canopy-map','vault-seed')) WHERE true
      ON CONFLICT(project_id,run_id,attempt_id) DO UPDATE SET claimed_at=excluded.claimed_at,origin=excluded.origin,task=excluded.task,value=excluded.value,estimate=excluded.estimate,cost_source=excluded.cost_source,live=excluded.live,counted=CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END
      WHERE (attempt_spend.claimed_at,attempt_spend.origin,attempt_spend.task,attempt_spend.value,attempt_spend.estimate,attempt_spend.cost_source,attempt_spend.live,attempt_spend.counted) IS NOT (excluded.claimed_at,excluded.origin,excluded.task,excluded.value,excluded.estimate,excluded.cost_source,excluded.live,CASE WHEN excluded.live=1 THEN 1 WHEN attempt_spend.counted=0 AND excluded.claimed_at<=attempt_spend.claimed_at THEN 0 ELSE excluded.counted END); END;

